"use strict";

// Expand a compact "sampled polygon" (polygons whose vertices are sampled over time, as
// generated by eclipsescraper's shadow.py) into CZML packets for Cesium.CzmlDataSource.
// Times are stored once per polygon as integer deltas (in 1/time_scale seconds after the
// epoch) and each vertex's longitudes and latitudes as integer deltas (in 1/coord_scale
// degrees). Version 1 is a single polygon with its fields at the top level; version 2 is a
// document with a name and a list of such polygons (each optionally named). Any polygon may
// have a granularity (radians). Mirrors
// expand_sampled_polygon() in eclipsescraper/src/eclipsescraper/shadow.py.
function expandSampledPolygon(compact) {
    if (compact.format !== "eclipsetracks.sampled_polygon" || (compact.version !== 1 && compact.version !== 2)) {
        throw new Error("Not a version 1 or 2 sampled polygon");
    }
    var packets = [{ id: "document", version: "1.1", name: compact.name }];
    var polygons = compact.version === 2 ? compact.polygons : [compact];
    polygons.forEach(function(polygon) {
        expandPolygon(polygon, compact.version === 2, packets);
    });
    return packets;
}

// Append one polygon's vertex packets, then the polygon packet, to packets
function expandPolygon(polygon, named, packets) {
    var n = polygon.times.length;
    var times = new Array(n);
    var t = 0;
    for (var k = 0; k < n; k++) {
        t += polygon.times[k];
        times[k] = t / polygon.time_scale;
    }
    var scale = polygon.coord_scale;
    var references = [];
    for (var i = 0; i < polygon.lon.length; i++) {
        var id = polygon.vertex_id.replace("{i}", String(i).padStart(2, "0"));
        var lonDeltas = polygon.lon[i];
        var latDeltas = polygon.lat[i];
        var samples = new Array(4 * n);
        var lon = 0;
        var lat = 0;
        for (var k = 0; k < n; k++) {
            lon += lonDeltas[k];
            lat += latDeltas[k];
            samples[4 * k] = times[k];
            samples[4 * k + 1] = lon / scale;
            samples[4 * k + 2] = lat / scale;
            samples[4 * k + 3] = 0;
        }
        packets.push({
            id: id,
            availability: polygon.availability,
            position: { epoch: polygon.epoch, cartographicDegrees: samples, interpolationAlgorithm: "LINEAR" }
        });
        references.push(id + "#position");
    }
    var packet = { id: polygon.id };
    if (named && polygon.name !== undefined) { packet.name = polygon.name; }
    packet.availability = polygon.availability;
    packet.polygon = {
        show: true,
        material: { solidColor: { color: { rgba: polygon.rgba } } }
    };
    if (polygon.granularity !== undefined) { packet.polygon.granularity = polygon.granularity; }
    packet.polygon.positions = { references: references };
    packets.push(packet);
}

// Allow use from Node (for validation scripts) as well as the browser bundle
if (typeof module !== "undefined" && module.exports) {
    module.exports = { expandSampledPolygon: expandSampledPolygon };
}
